public function setRobots($robots) {
	$this->robots = $robots;
}

public function getRobots() {
	return $this->robots;
}

if (isset($this->request->post['noindex'])) {
	$data['noindex'] = 1;
} elseif (!empty($information_info) && !empty($information_info['noindex'])) {
	$data['noindex'] = 1;
